  Theorem nstore_spec : ltac2:(zQ "ha0!hc!jf!km7!hk1!hld!jj5!hmd!lh7!kr0!kmf!hl6!hm4!lj7!lk5!hr4!ju3!hv9!ksa!ikf!ip9!iq5!iuf!jl3!kt1!kg7!krc>2t0@1$1@1$0#k0>2t1@1$1@1$0#k0>2t2@1$1@1$0#k0>2a1@1$1@1$0#k0>2a4@1$1@1$0#k0>2a5@1$1@1$0#k0>2a6@1$1@1$0#k0>2a7@1$1@1$0#k0>2t3@1$1@1$0#k0>2t4@1$1@1$0#k0>2t5@1$1@1$0#k0>2t6@1$1@1$0#k0>2j1@1$1@1$0#k0>2j2@1$1@1$0#k0>2j3@1$1@1$0#k0>0@4$8$3?1m?4ARGS@3$4$2@1$9@1$5?2TR@3$4$2@1$7@1$5?1n@3$4$2@1$7@1$5Z@1$6$2>0@4$8$3?1m?2ND@3$4$2@1$9^4@3$4$2@1$7^3@3$4$2@1$7^2@1$6$2>0@4$h3$3?1m?2TR?3src>0@4$8$3?1m+ipihg8@3$4$2@1$9@1$5?2Fr@1$6$2>0@4$8$3?1m+ipihh8@3$4$2@1$9@1$5?2SB@1$6$2>0@4$8$3?1m+ipihi0@3$4$2@1$7@1$5?2Fr@1$6$2>0@4$e$3?1m@2$h6?2SB@2$h7+8?2Fr?4junk>0@4$h1$3?1m?2lo@2$h9@1$0#k0?2sp>0@2$h4$3?1m@3$f$3@hb$d?2ra?2sp?2gp?2tp?2s0?2s1?2s2?2s3?2s4?2s5?2s6?2s7?2s8?2s9?3s10?3s11?1F?2fc?2lo?2ND?2SB?2Fr?1n?1h^b@2$b@1$1@1$0#8?4junk?1m@7$h2@hf$h0?2ra?2sp?2gp?2tp^h8^h7^h6?2s0?2s1@1$5?2ND^h5@1$5?4ARGS@1$5?1h^h4^h3^h2^h1?2s2?2s3?2s4?2s5?2s6?2s7?2s8?2s9?3s10?3s11^h0^f^e^d?1F@2$h8@1$0#k0$c?2fc@1$a@1$1@1$0#k0?1m@1$h5$3").
